parameters.jsCode:
const wb  = $('Webhook: Record Member Payment').first().json.body || {};
const inv = $('DB: Update Invoice').first().json;
const pmt = $('DB: Insert Payment Record').first().json;

const name    = wb.customer_name || 'Member';
const email   = wb.customer_email || '';
const month   = inv.invoice_month || '';
const total   = parseFloat(inv.total_amount || 0).toFixed(2);
const paid    = parseFloat(inv.amount_paid  || 0).toFixed(2);
const balance = parseFloat(inv.balance_due  || 0).toFixed(2);
const ref     = pmt.reference_number || '7-';
const method  = wb.payment_method || 'N/A';
const amount  = parseFloat(wb.amount || 0).toFixed(2);
const status  = inv.status || 'partial';

const statusColour = status === 'paid' ? '#27ae60' : '#e67e22';
const statusLabel  = status === 'paid' ? 'PAID IN FULL' : 'PARTIAL PAYMENT';

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: Arial, sans-serif; color: #333; max-width: 600px; margin: 0 auto; }
    .header { background: #2c3e50; color: white; padding: 24px; text-align: center; }
    .header h1 { margin: 0; font-size: 20px; }
    .body { padding: 24px; }
    .invoice-box { border: 1px solid #ddd; border-radius: 6px; overflow: hidden; margin: 16px 0; }
    .invoice-row { display: flex; justify-content: space-between; padding: 10px 16px; border-bottom: 1px solid #eee; }
    .invoice-row:last-child { border-bottom: none; }
    .invoice-row.total { background: #f8f9fa; font-weight: bold; }
    .status-badge { display: inline-block; background: ${statusColour}; color: white; padding: 4px 12px; border-radius: 20px; font-size: 12px; font-weight: bold; }
    .footer { background: #f5f5f5; padding: 16px; text-align: center; font-size: 12px; color: #999; }
  </style>
</head>
<body>
  <div class="header">
    <h1>Payment Receipt</h1>
    <p style="margin:8px 0 0;">Reference: ${ref}</p>
  </div>
  <div class="body">
    <p>Hi ${name},</p>
    <p>Thank you — we've received your payment. Here is your receipt for the period <strong>${month}</strong>.</p>
    <p><span class="status-badge">${statusLabel}</span></p>
    <div class="invoice-box">
      <div class="invoice-row"><span>Invoice Period</span><span>${month}</span></div>
      <div class="invoice-row"><span>Payment Method</span><span>${method}</span></div>
      <div class="invoice-row"><span>Amount Paid (this transaction)</span><span>&pound;${amount}</span></div>
      <div class="invoice-row"><span>Total Invoice Amount</span><span>&pound;${total}</span></div>
      <div class="invoice-row"><span>Total Paid to Date</span><span>&pound;${paid}</span></div>
      <div class="invoice-row total"><span>Remaining Balance</span><span>&pound;${balance}</span></div>
    </div>
    <p>Please retain this email as your receipt. Reference number: <strong>${ref}</strong></p>
    <p>Warm regards,<br>The Venue Team</p>
  </div>
  <div class="footer">
    This receipt was sent to ${email}. Please do not reply directly to this email.
  </div>
</body>
</html>`;

return [{ json: { to: email, subject: `Payment Receipt — ${month} (${ref})`, html } }];

parameters.responseBody:
={{ JSON.stringify({
  status: 'ok',
  invoice: $('DB: Update Invoice').first().json,
  payment: $('DB: Insert Payment Record').first().json
}) }}
